  "implementation": "def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n.get('parent')
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    root_id = next(n['id'] for n in nodes if n['parent'] is None)
    retained = []
    visit_order = []

    def dfs(node_id):
        node = node_map[node_id]
        if node['removable'] and node['utility'] < threshold:
            return
        retained.append(node_id)
        visit_order.append(node_id)
        for child_id in sorted(children.get(node_id, [])):
            dfs(child_id)

    dfs(root_id)

    return {'retained_node_ids': retained, 'visit_order': visit_order}
